from .base_config import EditableConfig


class HeatTemplate(EditableConfig):

    """
    It sets attributes delivered by parameter 'cfg_dict' to dictionary according to the scheme {'key': 'value'}

    :param ENV: ENV
    :param YAML: YAML
    """

    ENV = 'env'
    YAML = 'yaml'

    def __init__(self, cfg_dict):

        """
        Assigns all attributes from parameter cfg_dict

        :param cfg_dict: Dictionary containing ip addresses and names of the hosts
        Example of [key, value] --> ['oam_ip', '1.1.11.2']
        """

        super(HeatTemplate, self).__init__()
        self._set_all_attributes(cfg_dict)

    def _set_all_attributes(self, attributes_dict):

        """
        Assigns attributes from parameter attributes_dict to attributes of this method

        :param attributes_dict: provides attributes from directory to set them by method
        """

        for key, val in attributes_dict.items():
            self._set_attr(key, val)

    @property
    def dict(self):

        """
        :return: dict of attributes assigns in method _set_all_attributes
        """

        return {'parameters': dict(self._attributes)}


class BTSHeatTemplate(HeatTemplate):

    """BTS Heat Template initialization"""

    def __init__(self, cfg_dict):
        super(BTSHeatTemplate, self).__init__(cfg_dict=cfg_dict)


class ExtNetHeatTemplate(HeatTemplate):

    """ExtNetHeatTemplate initialization"""

    def __init__(self, cfg_dict):
        super(ExtNetHeatTemplate, self).__init__(cfg_dict=cfg_dict)


class HeatStacks(object):

    """
    Assigns values to bts and net

    :param bts: BTS Heat Template
    :param net: Ext Net Heat Template
    """

    def __init__(self, bts, net):
        self.bts = bts
        self.net = net
